{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "AccountBreached.v1.json",
 "title": "Alpha One — event AccountBreached v1",
 "description": "V1 catalog event `AccountBreached` (v1). Envelope per EVT-03 (see envelope.schema.json). Producer/consumers per contracts/events/catalog.md: consumers = NOT-01 (template: breach), ANA-01. Derived from: docs/07 §3.2 (ACTIVE→BREACH_DETECTED side effect 'AccountBreached (LCC-23)'); verdict fields per docs/09 §3.3/§3.4 (rule, limit_cents, tolerance_cents, input_hash) and docs/32 `evaluations`. Money is integer minor units (docs/00 #3); the envelope carries tenant_id — no redundant tenant field in the payload.",
 "allOf": [
  {
   "$ref": "envelope.schema.json#/$defs/envelope"
  },
  {
   "properties": {
    "type": {
     "const": "AccountBreached"
    },
    "version": {
     "const": 1
    },
    "payload": {
     "type": "object",
     "properties": {
      "account_id": {
       "$ref": "envelope.schema.json#/$defs/ULID"
      },
      "phase": {
       "type": "integer",
       "minimum": 1
      },
      "rule": {
       "type": "string",
       "description": "the breached rule id (e.g. max_daily_loss, max_total_loss, time_limit — D30)"
      },
      "verdict_id": {
       "$ref": "envelope.schema.json#/$defs/ULID"
      },
      "evidence_ref": {
       "type": "string",
       "description": "pointer to the EVL evidence snapshot (evaluations.detail: metrics at decision time)"
      },
      "observed_cents": {
       "type": "integer"
      },
      "limit_cents": {
       "type": "integer"
      },
      "tolerance_cents": {
       "type": "integer",
       "description": "EVL-53 comparison tolerance (default 1¢, docs/09 §3.3)"
      },
      "breached_at": {
       "$ref": "envelope.schema.json#/$defs/TimestampMs"
      }
     },
     "additionalProperties": false,
     "required": [
      "account_id",
      "phase",
      "rule",
      "verdict_id",
      "breached_at"
     ]
    }
   },
   "required": [
    "type",
    "version",
    "payload"
   ]
  }
 ]
}

