{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "bridge.tick.v1.json",
 "title": "Alpha One — event bridge.tick v1",
 "description": "V1 catalog event `bridge.tick` (v1). Envelope per EVT-03 (see envelope.schema.json). Producer/consumers per contracts/events/catalog.md: consumers = EVL (evaluate), ANA (equity points), web SSE fan-out (TD live) — observed record per EVL-49; no audit mirror (docs/05 §14). Derived from: docs/08 §8 (canonical tick shape — D34, docs/51: positions array, margin/free_margin, leverage-as-string, deals_count, last_deal_ticket; D79, docs/63: optional trigger/source/stream_seq/equity_low_cents/equity_high_cents); money cents per docs/32 `account_snapshots`/`broker_accounts`. Money is integer minor units (docs/00 #3); the envelope carries tenant_id — no redundant tenant field in the payload.",
 "allOf": [
  {
   "$ref": "envelope.schema.json#/$defs/envelope"
  },
  {
   "properties": {
    "type": {
     "const": "bridge.tick"
    },
    "version": {
     "const": 1
    },
    "payload": {
     "type": "object",
     "properties": {
      "account_id": {
       "$ref": "envelope.schema.json#/$defs/ULID"
      },
      "broker_login": {
       "type": "string"
      },
      "equity_cents": {
       "type": "integer",
       "description": "broker-reported equity in cents — never recomputed, broker is truth (docs/09 §3.3)"
      },
      "balance_cents": {
       "type": "integer"
      },
      "margin_cents": {
       "type": "integer"
      },
      "free_margin_cents": {
       "type": "integer"
      },
      "leverage": {
       "type": "string",
       "description": "e.g. 1:500 (string — D34 fixed the invalid-number form)"
      },
      "positions": {
       "type": "array",
       "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "position_id",
         "symbol",
         "side",
         "lots",
         "open_price",
         "opened_at"
        ],
        "properties": {
         "position_id": {
          "type": "string"
         },
         "symbol": {
          "type": "string"
         },
         "side": {
          "type": "string",
          "enum": [
           "buy",
           "sell"
          ]
         },
         "lots": {
          "type": "number",
          "description": "lot size (a quantity, not money)"
         },
         "open_price": {
          "type": "number",
          "description": "instrument price (an asset/asset ratio, not money — the integer-minor-units rule applies to amounts, docs/00 #3)"
         },
         "current_price": {
          "type": [
           "number",
           "null"
          ]
         },
         "sl": {
          "type": [
           "number",
           "null"
          ]
         },
         "tp": {
          "type": [
           "number",
           "null"
          ]
         },
         "opened_at": {
          "$ref": "envelope.schema.json#/$defs/TimestampMs"
         },
         "profit_cents": {
          "type": "integer"
         },
         "swap_cents": {
          "type": "integer"
         },
         "commission_cents": {
          "type": "integer"
         }
        }
       },
       "description": "open positions at tick time (TD live view, RSK V2)"
      },
      "deals_count": {
       "type": "integer",
       "minimum": 0
      },
      "last_deal_ticket": {
       "type": "integer",
       "description": "incremental fetch cursor (D33: never a continuity oracle)"
      },
      "broker_time": {
       "$ref": "envelope.schema.json#/$defs/TimestampMs"
      },
      "trigger": {
       "type": "string",
       "enum": [
        "deal",
        "position",
        "guard",
        "material",
        "heartbeat",
        "resync"
       ],
       "description": "why the streaming conflator emitted this tick (D79, docs/63 §4.4); evidence only — never a rule input. Absent on fallback-poll ticks"
      },
      "source": {
       "type": "string",
       "enum": [
        "stream",
        "poll",
        "resync"
       ],
       "description": "ingest path (D78): stream = MetaApi streaming, poll = credit-budgeted REST fallback, resync = post-(re)synchronization full state"
      },
